Clase Jugador
    Privado Definir goles Como Entero;

    Metodo Constructor(unosGoles Como Entero)
        Este.goles <- unosGoles;
    FinMetodo

    Publico Metodo Goles() Como Entero
        Retornar Este.goles;
    FinMetodo
FinClase

Clase Equipo
    Privado Definir jugador1 Como Jugador;
    Privado Definir jugador2 Como Jugador;

    Metodo Constructor(unosGoles1 Como Entero, unosGoles2 Como Entero)
        Este.jugador1 <- Nuevo Jugador(unosGoles1);
        Este.jugador2 <- Nuevo Jugador(unosGoles2);
    FinMetodo

    Publico Metodo TotalGoles() Como Entero
        Retornar Este.jugador1.Goles() + Este.jugador2.Goles();
    FinMetodo
FinClase

Proceso CalcularTotalGoles
    Definir g1 Como Entero;
    Definir g2 Como Entero;
    Definir equipo Como Equipo;
    Leer g1;
    Leer g2;
    equipo <- Nuevo Equipo(g1, g2);
    Escribir equipo.TotalGoles();
FinProceso
